import{_ as o,c as a,o as t,aj as i}from"./chunks/framework.Bfdr4H5E.js";const y=JSON.parse('{"title":"Terms and Conditions","description":"","frontmatter":{"outline":"deep","prev":{"text":"Disclaimer Policy","link":"/disclaimer-policy"},"next":{"text":"Refund Policy","link":"/refund-policy"}},"headers":[],"relativePath":"terms-and-conditions.md","filePath":"terms-and-conditions.md"}'),r={name:"terms-and-conditions.md"};function n(s,e,d,l,c,u){return t(),a("div",null,e[0]||(e[0]=[i('<h1 id="terms-and-conditions" tabindex="-1">Terms and Conditions <a class="header-anchor" href="#terms-and-conditions" aria-label="Permalink to &quot;Terms and Conditions&quot;">​</a></h1><p><strong>PLEASE READ THESE TERMS AND CONDITIONS OF USE CAREFULLY BEFORE USING THIS WEBSITE.</strong></p><p>This website is written and published by YS Trading Coach.<br> If you continue to browse and use this website you are agreeing to comply with and be bound by the following terms and conditions of use, which together with our <a href="/sk/privacy-policy/">privacy policy</a> and <a href="/sk/disclaimer/">website disclaimer</a>, govern YS Trading Coach’s relationship with you in relation to your use of this website.</p><p>By using this website, you signify your acceptance of these terms and conditions of use. For the purposes of these terms and conditions, “Us”, “Our” and “We” refers to YS Trading Coach and “You” and “Your” refers to you, the client, visitor, website user or person using our website.</p><h4 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h4><p>By using this website you agree and accept that that these Terms and Conditions relate not only to the ystc.in website and content but also all associated and related courses, products, services, and webpages, and all mediums of communication including text, video, audio and image.</p><h4 id="amendment-of-terms" tabindex="-1">Amendment of Terms <a class="header-anchor" href="#amendment-of-terms" aria-label="Permalink to &quot;Amendment of Terms&quot;">​</a></h4><p>We reserve the right to change, modify, add or remove portions of these terms at any time. Please check these terms regularly prior to using our website to ensure you are aware of any changes. We will endeavor to highlight any significant or substantive changes to you where possible. If you choose to use our website then we will regard that use as conclusive evidence of your agreement and acceptance that these terms govern your and YS Trading Coach’s rights and obligations to each other.</p><h4 id="reliance-on-content" tabindex="-1">Reliance on Content <a class="header-anchor" href="#reliance-on-content" aria-label="Permalink to &quot;Reliance on Content&quot;">​</a></h4><p>The information, facts, insights, products and ideas (“Content”) are for general information and educational purposes only. Nothing contained in it is or is intended to be or construed as personal professional, investment or financial advice as it does not take into account your individual objectives, financial situation or needs. It should not be used, relied upon or treated as a substitute for specific or professional advice. It is for education and information purposes and to help you determine your own course of action but does not consider your personal situation. The products may suit your needs or they may not be appropriate for your own personal trading style but you are using any Content at your own risk and we make no guarantees as to any use, suitability, trading success or financial gain.The trading market is a volatile subject and no amount of past methodology can predict future results. The reliability of data provided here is based on probabilities only.</p><p>You should, before you act on or use any of this Content, consider the appropriateness of this information and products having regard to your own personal objectives, financial situation and needs and consult a professional. It should not be your only source of information but should be treated as a guide only. You should obtain your own independent professional advice before making any decision based on this information and you agree that you use this website and any Content at your own risk.</p><h4 id="limitation-of-liability" tabindex="-1">Limitation of Liability <a class="header-anchor" href="#limitation-of-liability" aria-label="Permalink to &quot;Limitation of Liability&quot;">​</a></h4><p>It is an essential pre-condition to you using our website that you agree and accept that YS Trading Coach is not legally responsible for any loss or damage you might suffer related to your use of the website, whether from errors or from omissions in our documents or information, any goods or services we may offer or from any other use of the website. Your use of any information or materials on this website is entirely at your own risk, for which we shall not be liable.</p><p>It shall be your own responsibility to ensure that any products, services or information available through this website meet your specific, personal requirements. You acknowledge that such information and materials may contain inaccuracies or errors and we expressly exclude liability for any such inaccuracies or errors to the fullest extent permitted by law.</p><h4 id="delivery-of-physical-goods" tabindex="-1">Delivery of Physical Goods <a class="header-anchor" href="#delivery-of-physical-goods" aria-label="Permalink to &quot;Delivery of Physical Goods&quot;">​</a></h4><p>YS Trading Coach uses Indian Post and/or other reputable courier companies to deliver physical goods.</p><p>Deliveries are processed promptly upon receipt of full payment. Delivery may take between 2 and 14 days, depending on the delivery company chosen. YS Trading Coach is not responsible for goods that are either damaged in transit or not received. Damaged or lost orders should be resolved with Indian Post or the courier company directly. Replacement of damaged or lost items is made at the discretion of YS Trading Coach.</p><h4 id="returns-and-refunds-only-physical-goods" tabindex="-1">Returns and Refunds (Only Physical Goods) <a class="header-anchor" href="#returns-and-refunds-only-physical-goods" aria-label="Permalink to &quot;Returns and Refunds (Only Physical Goods)&quot;">​</a></h4><p>YS Trading Coach handles returns and processes refunds in accordance with the Indian Consumer Protection legislation. For non-tangible, irrevocable goods please check <a href="/sk/refund-policy/">Refund Policy</a>.</p><p>Should you wish to return your order (Only Physical Goods), please notify us within 14 days of purchase with a valid reason for return. If we are unable to resolve your complaint or further assist you, we will process a refund upon timely receipt of the goods purchased. Unopened goods will be refunded in full. Refunds will be processed promptly and payment made by the same method that you made payment. Refund payments may take up to 7 business days to be received. Refunds are made at the discretion of YS Trading Coach.</p><h4 id="links-to-other-website" tabindex="-1">Links to other website <a class="header-anchor" href="#links-to-other-website" aria-label="Permalink to &quot;Links to other website&quot;">​</a></h4><p>YS Trading Coach may from time to time provide on its website, links to other websites and information on those websites for your convenience. This does not necessarily imply sponsorship, endorsement, or approval or arrangement between YS Trading Coach and the owners of those websites. YS Trading Coach takes no responsibility for any of the content found on the linked websites.</p><p>YS Trading Coach’s website may contain information provided by third parties for which YS Trading Coach accepts no responsibility whatsoever for information or advice provided to you directly by third parties. We are making a ‘recommendation’ only and are not providing any advice nor do we take any responsibility for any advice received in this regard.</p><h4 id="disclaimer" tabindex="-1">Disclaimer <a class="header-anchor" href="#disclaimer" aria-label="Permalink to &quot;Disclaimer&quot;">​</a></h4><p>To the fullest extent permitted by law, YS Trading Coach absolutely disclaims all warranties, expressed or implied, including, but not limited to, implied warranties of merchantability and fitness for any particular purpose. YS Trading Coach gives no warranty that the documents, goods or services will be free of errors, or that defects will be corrected, or that our website or its server is free of viruses or any other harmful components.</p><p>Whilst we, at all times endeavour to have the most accurate, reliable and up-to-date information on our website, we do not warrant or make any representations regarding the use or the result of the use of any document, product, service, link or information in its website or as to their correctness, suitability, accuracy, reliability, or otherwise.</p><p>It is your sole responsibility and not the responsibility of YS Trading Coach to bear any entire costs of servicing, repairs, or correction. The applicable law in your state or territory may not permit these exclusions, particularly the exclusions of some implied warranties. Some of the above may not apply to you but you must ensure you are aware of any risk you may be taking by using this website or any products or services that may be offered through it. It is your responsibility to do so.</p><h4 id="education" tabindex="-1">Education <a class="header-anchor" href="#education" aria-label="Permalink to &quot;Education&quot;">​</a></h4><p>By using our services, you agree that YS Trading Coach is not to be held liable for any decisions you make based on any of our services or guidance and any consequences, as a result, are your own. Under no circumstances can you hold YS Trading Coach liable for any actions you take nor can you hold us or any of our employees liable for any loss or costs incurred by you as a result of any guidance, advice, coaching, materials or techniques used or provided by YS Trading Coach.</p><p>All our information on both the website and in consultations is intended to assist you and does not in any way, nor is it intended to substitute professional, financial or legal advice. Results are not guaranteed and YS Trading Coach takes no responsibility for your actions, choices or decisions.</p><p>Reference to any market, trading timeframe, analysis style or trading technique is for the purposes of information and education only. They are not to be considered a recommendation as being appropriate to your circumstances or needs.</p><p>All charting and analysis platforms referred to or used in our articles and videos have been chosen because of compatibility with our screen capture software. These charting and analysis platforms are being used to demonstrate and explain a trading concept, for the purposes of information and education only. They are not necessarily used by us in our live trading, and are in no way recommended as being suitable for your trading purposes.</p><p>All chart layouts (including timeframes, indicators and parameters) within our articles and videos are being used to demonstrate and explain a trading concept, for the purposes of information and education only. These chart layouts are not necessarily used by us in our live trading, and are in no way recommended as being suitable for your trading purposes.</p><p>Unless specifically stated otherwise, all trade setups and trades shown within our articles and videos are to be considered hypothetical, selected after the fact in order to demonstrate a trading concept for the purposes of information and education only.</p><h4 id="third-party-material" tabindex="-1">Third Party Material: <a class="header-anchor" href="#third-party-material" aria-label="Permalink to &quot;Third Party Material:&quot;">​</a></h4><p>This website may contain content by guest authors. Any web links, or URLs, within any guest articles or videos are included as professional courtesy, and in many cases are a publishing requirement. However, please understand that their article or video has been included because we believe their content provides educational value for many traders. In no way are we providing an endorsement of the author’s website, newsletter, courses, or any other materiel, unless specifically stated. In addition, we are not liable for any loss, claims, or damage incurred by any person, due to any errors or omissions, or as a consequence of the use or reliance on any third-party website or products, or any information contained within.</p><h4 id="affiliate-referral-commission-disclosure" tabindex="-1">Affiliate / Referral Commission Disclosure: <a class="header-anchor" href="#affiliate-referral-commission-disclosure" aria-label="Permalink to &quot;Affiliate / Referral Commission Disclosure:&quot;">​</a></h4><p>You should always assume that the owner of this website has an affiliate relationship, or some other form of referral relationship, with the providers of goods or services mentioned or linked to within our material, and may be compensated when you register with these providers or purchase their goods or services. You should conduct due diligence of all products or services before making any purchase decisions, to ensure that they meet your personal needs and that you understand and are satisfied with any terms and conditions and refund policy. We are not liable for any loss, claims, or damage incurred by any person, due to any errors or omissions, or as a consequence of the use or reliance on any third-party website or products, or any information contained within.<br> As an Amazon Associate. We earn from qualifying purchases.</p><h4 id="testimonials" tabindex="-1">Testimonials: <a class="header-anchor" href="#testimonials" aria-label="Permalink to &quot;Testimonials:&quot;">​</a></h4><p>All testimonials provided on YS Trading Coach and associated products, services and webpages are real. File copies have been retained by the publisher. It is important to note that individual results may vary. A testimonial provided by one client may not be representative of all client experiences. Past performance does not guarantee future performance.</p><h4 id="securities-and-exchange-board-of-india-sebi-required-disclaimer" tabindex="-1">Securities and Exchange Board of India (SEBI) required Disclaimer: <a class="header-anchor" href="#securities-and-exchange-board-of-india-sebi-required-disclaimer" aria-label="Permalink to &quot;Securities and Exchange Board of India (SEBI) required Disclaimer:&quot;">​</a></h4><p>Futures Trading and Options trading has large potential rewards, but also large potential risk. You must be aware of the risks and be willing to accept them in order to invest in the futures and options markets. Don’t trade with money you can’t afford to lose. This is neither a solicitation nor an offer to Buy/Sell futures or options. No representation is being made that any account will or is likely to achieve profits or losses similar to those discussed on this web site. The past performance of any trading system or methodology is not necessarily indicative of future results. The reliability of data provided here is based on probabilities only. While actually investing in the market all the decisions regarding trading are to be taken by the trader himself.</p><p>HYPOTHETICAL OR SIMULATED PERFORMANCE RESULTS HAVE CERTAIN LIMITATIONS. UNLIKE AN ACTUAL PERFORMANCE RECORD, SIMULATED RESULTS DO NOT REPRESENT ACTUAL TRADING. ALSO, SINCE THE TRADES HAVE NOT BEEN EXECUTED, THE RESULTS MAY HAVE UNDER-OR-OVER COMPENSATED FOR THE IMPACT, IF ANY, OF CERTAIN MARKET FACTORS, SUCH AS LACK OF LIQUIDITY. SIMULATED TRADING PROGRAMS IN GENERAL ARE ALSO SUBJECT TO THE FACT THAT THEY ARE DESIGNED WITH THE BENEFIT OF HINDSIGHT. NO REPRESENTATION IS BEING MADE THAT ANY ACCOUNT WILL OR IS LIKELY TO ACHIEVE PROFIT OR LOSSES SIMILAR TO THOSE SHOWN</p><h4 id="your-privacy" tabindex="-1">Your Privacy <a class="header-anchor" href="#your-privacy" aria-label="Permalink to &quot;Your Privacy&quot;">​</a></h4><p>At YS Trading Coach, we are committed to protecting your privacy. We use the information we collect about you to maximize the services that we provide to you. YS Trading Coach respects the privacy and confidentiality of the information provided by you and adheres to the Indian Privacy Principles. Please read our separate Privacy Policy carefully <a href="/sk/privacy-policy/">here</a>.</p><p>You may change your details at any time by advising us in writing via email. All information we receive from our customers, is protected by our secure servers. YS Trading Coach’s secure server software encrypts all customer information before it is sent to us. Furthermore, all of the customer data YS Trading Coach collects is secured against unauthorized use or access. Credit card information is not stored by us on our servers.</p><h6 id="third-parties" tabindex="-1">Third Parties <a class="header-anchor" href="#third-parties" aria-label="Permalink to &quot;Third Parties&quot;">​</a></h6><p>YS Trading Coach does not and will not sell or deal in personal or customer information. We may however use in a general sense without any reference to your name, your information to create marketing statistics, identify user demands and to assist it in meeting customer needs generally. In addition, we may use the information that you provide to improve our website and its services but not for any other use.</p><h6 id="disclose-your-information" tabindex="-1">Disclose your information <a class="header-anchor" href="#disclose-your-information" aria-label="Permalink to &quot;Disclose your information&quot;">​</a></h6><p>YS Trading Coach may be required, in certain circumstances, to disclose information in good faith and where YS Trading Coach is required to do so in the following circumstances: by law or by any court; to enforce the terms of any of our customer agreements; or to protect the rights, property or safety of YS Trading Coach, its customers or third parties.</p><h6 id="exclusion-of-competitors" tabindex="-1">Exclusion of Competitors <a class="header-anchor" href="#exclusion-of-competitors" aria-label="Permalink to &quot;Exclusion of Competitors&quot;">​</a></h6><p>If you are in the business of creating similar documents, goods or services for the purpose of providing them for a fee to users, whether they be business users or domestic users, then you are a competitor of YS Trading Coach. YS Trading Coach expressly excludes and does not permit you to use or access its website, to download any documents or information from its website or obtain any such documents or information through a third party. If you breach this term then YS Trading Coach will hold you fully responsible for any loss that it might sustain and further holds you accountable for all profits that you might make from such unpermitted and improper use. YS Trading Coach reserves the right to exclude and not permit any person from using its website or any of the documents and information contained on it.</p><h4 id="copyright-trademark-and-restrictions-of-use" tabindex="-1">Copyright, Trademark and Restrictions of use <a class="header-anchor" href="#copyright-trademark-and-restrictions-of-use" aria-label="Permalink to &quot;Copyright, Trademark and Restrictions of use&quot;">​</a></h4><p>This website contains material which is owned by or licensed to us. This material includes, but is not limited to, the design, layout, look, appearance, trademarks and graphics. You are not permitted to reproduce the documents, information or materials on the website for the purposes of sale or the use by any third party. In particular you are not permitted to republish, upload, transmit electronically or otherwise or distribute any of the materials, documents or products that may be available for download from time to time on this website.</p><p>YS Trading Coach expressly reserves all copyright and trademark in its website and in all documents and information on its website and reserves the right to take action against you if you breach any of these terms.</p><p>Any redistribution or reproduction of part or all of the contents in any form is prohibited other than the following: you may print or download to a local hard disk extracts for your personal and non-commercial use only; and you may copy the content to individual third parties for their personal use, but only if you acknowledge the website as the source of the material.</p><p>You may not, except with our express written permission, distribute or commercially exploit the content. Nor may you transmit it or store it in any other website or other form of electronic retrieval system.</p><h5 id="whole-agreement" tabindex="-1">Whole Agreement <a class="header-anchor" href="#whole-agreement" aria-label="Permalink to &quot;Whole Agreement&quot;">​</a></h5><p>These terms and conditions represent the whole agreement between you and YS Trading Coach concerning your use and access to YS Trading Coach’s website and your use and access to the documents and information on it. No other term is to be included in this agreement except where it is required to be included by any legislation of the Commonwealth or any State or Territory. All implied terms except those implied by statute and which cannot be expressly excluded are hereby expressly excluded.</p><h4 id="exclusion-of-unenforceable-terms" tabindex="-1">Exclusion of Unenforceable Terms <a class="header-anchor" href="#exclusion-of-unenforceable-terms" aria-label="Permalink to &quot;Exclusion of Unenforceable Terms&quot;">​</a></h4><p>Where any clause or term above would by any applicable statute be illegal, void, or unenforceable in any State or Territory then such a clause shall not apply in that State or Territory and shall be deemed never to have been included in these terms and conditions in that State or Territory. Such a clause if legal and enforceable in any other State or Territory shall continue to be fully enforceable and part of this agreement in those other States and Territories. The deemed exclusion of any term pursuant to this paragraph shall not affect or modify the full enforceability and construction of the other clauses of these terms and conditions.</p><h4 id="jurisdiction" tabindex="-1">Jurisdiction <a class="header-anchor" href="#jurisdiction" aria-label="Permalink to &quot;Jurisdiction&quot;">​</a></h4><p>This agreement and this website are subject to the laws of India. If there is a dispute between you and YS Trading Coach that results in litigation then you must submit to the jurisdiction of the courts of India.</p>',63)]))}const m=o(r,[["render",n]]);export{y as __pageData,m as default};
